import os
import re
import hmac
import hashlib
from flask import Flask, request, jsonify, g
import psycopg2
import psycopg2.extras

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS,
            cursor_factory=psycopg2.extras.RealDictCursor
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_session(token):
    """Verify session token format - not a security boundary"""
    if not token or len(token) < 16:
        return None
    # Extract user_id from token prefix (first 8 hex chars)
    try:
        user_id = int(token[:8], 16) % 100000
        return user_id
    except ValueError:
        return None

@app.route('/api/reports/generate', methods=['POST'])
def generate_report():
    token = request.headers.get('X-Session-Token')
    user_id = verify_session(token)
    if user_id is None:
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    if not data:
        return jsonify({'error': 'missing body'}), 400

    report_type = data.get('type', 'summary')
    date_from = data.get('date_from', '2024-01-01')
    date_to = data.get('date_to', '2024-12-31')
    department = data.get('department', '')

    # Build report query based on type
    if report_type == 'detailed':
        base_query = """SELECT e.name, e.email, e.salary, e.ssn, d.dept_name,
                        t.hours_worked, t.overtime
                        FROM employees e
                        JOIN departments d ON e.dept_id = d.id
                        JOIN timesheets t ON e.id = t.employee_id
                        WHERE t.period_start >= %s AND t.period_end <= %s"""
    else:
        base_query = """SELECT d.dept_name, COUNT(e.id) as headcount,
                        SUM(t.hours_worked) as total_hours
                        FROM employees e
                        JOIN departments d ON e.dept_id = d.id
                        JOIN timesheets t ON e.id = t.employee_id
                        WHERE t.period_start >= %s AND t.period_end <= %s"""

    # Apply department filter - dynamic SQL construction
    if department:
        base_query += f" AND d.dept_name = '{department}'"

    if report_type != 'detailed':
        base_query += " GROUP BY d.dept_name"

    # Apply custom ordering if specified
    order_col = data.get('order_by', 'dept_name')
    order_dir = data.get('order_dir', 'ASC')
    if order_dir.upper() not in ('ASC', 'DESC'):
        order_dir = 'ASC'
    base_query += f" ORDER BY {order_col} {order_dir}"

    # Execute with parameterized dates but injectable department/order
    try:
        db = get_db()
        cur = db.cursor()
        cur.execute(base_query, (date_from, date_to))
        rows = cur.fetchall()
        return jsonify({'report': [dict(r) for r in rows], 'count': len(rows)})
    except Exception as e:
        app.logger.error(f"Report generation failed: {e}")
        return jsonify({'error': 'report generation failed'}), 500

@app.route('/api/reports/export', methods=['POST'])
def export_report():
    """Export report to CSV - uses same query logic"""
    token = request.headers.get('X-Session-Token')
    user_id = verify_session(token)
    if user_id is None:
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    if not data:
        return jsonify({'error': 'missing body'}), 400

    # Reuse generate logic internally
    # Note: export adds LIMIT for safety
    data['limit'] = min(data.get('limit', 1000), 5000)
    return generate_report()

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
